use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list.len() == list.len(),
        // Left rotation by n:
        // new_list = list[n..] ++ list[..n]
        forall|i: int|
            0 <= i < (list.len() - n) as int ==>
                new_list[i] == list[n as int + i],
        forall|i: int|
            0 <= i < n as int ==>
                new_list[(list.len() - n) as int + i] == list[i],
{
    let len = list.len();
    let mut new_list: Vec<i32> = Vec::with_capacity(len);

    let mut i: usize = n;
    while i < len
        invariant
            n < len,
            len == list.len(),
            n <= i <= len,
            new_list.len() == i - n,
            forall|k: int|
                0 <= k < new_list.len() as int ==>
                    new_list[k] == list[n as int + k],
    {
        new_list.push(list[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < n
        invariant
            n < len,
            len == list.len(),
            0 <= j <= n,
            new_list.len() == (len - n) + j,
            forall|k: int|
                0 <= k < (len - n) as int ==>
                    new_list[k] == list[n as int + k],
            forall|k: int|
                0 <= k < j as int ==>
                    new_list[(len - n) as int + k] == list[k],
    {
        new_list.push(list[j]);
        j += 1;
    }

    new_list
}

} // verus!